import os

from .errors import InvalidNameError
from .rules import is_valid
from .sanitize import sanitize as _sanitize


class FileStore:
    """把名称映射到 ``root`` 目录下文件的简单存储。

    ``root`` 不存在时会被创建。同一个存储实例会记住已经写入过的名称，
    :meth:`list_names` 按写入顺序返回它们。

    名称在写入之前一律先经过 :func:`~wsafename.sanitize.sanitize`：净化
    结果不可用（空名称、Win32 保留设备名等）时抛
    :class:`~wsafename.errors.InvalidNameError`，磁盘上不会留下任何条目。
    """

    def __init__(self, root):
        self.root = os.path.abspath(root)
        os.makedirs(self.root, exist_ok=True)
        self._names = []

    # -- 名称 ---------------------------------------------------------------

    def sanitize(self, name):
        """返回 ``name`` 在本存储中使用的落盘名称。"""
        return _sanitize(name)

    def target_path(self, name):
        """返回 ``name`` 对应的绝对路径（不检查该条目是否存在）。

        ``name`` 净化后不可用时抛
        :class:`~wsafename.errors.InvalidNameError`。
        """
        return os.path.join(self.root, self.sanitize(name))

    def _query_path(self, name):
        """给查询类操作用：名称不可用时返回 ``None``，而不是抛异常。"""
        try:
            return self.target_path(name)
        except InvalidNameError:
            return None

    # -- 读写 ---------------------------------------------------------------

    def exists(self, name):
        """``name`` 对应的条目当前是否存在于磁盘上。

        不可用的名称不可能有对应条目，因此返回 ``False``。
        """
        path = self._query_path(name)
        return path is not None and os.path.isfile(path)

    def save(self, name, data):
        """把 ``data``（bytes）写入 ``name`` 对应的文件，返回落盘名称。"""
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes-like")

        # 先净化再校验：非法名称必须在触碰磁盘之前就被拒绝，
        # 这样调用方拿到的是 InvalidNameError 而不是底层 OSError，
        # 目标目录里也不会留下半成品条目。
        target = self.sanitize(name)

        if not is_valid(target):
            raise InvalidNameError("%r is not usable on Windows" % (target,))

        with open(os.path.join(self.root, target), "wb") as fh:
            fh.write(bytes(data))

        if target not in self._names:
            self._names.append(target)
        return target

    def load(self, name):
        """读回 ``name`` 对应的内容。

        名称不可用时抛 :class:`~wsafename.errors.InvalidNameError`，
        而不是让底层 ``OSError`` 冒出来。
        """
        with open(self.target_path(name), "rb") as fh:
            return fh.read()

    def list_names(self):
        """按写入顺序返回本存储已经写入过的名称。"""
        return list(self._names)

    def delete(self, name):
        """删除 ``name`` 对应的条目；条目不存在时返回 ``False``。"""
        path = self._query_path(name)
        if path is None or not os.path.isfile(path):
            return False
        os.remove(path)
        target = os.path.basename(path)
        if target in self._names:
            self._names.remove(target)
        return True

import os
import tempfile

from wsafename import FileStore, InvalidNameError, sanitize

RESERVED = ["CON.txt", "NUL.log", "lpt1.tar.gz", "con", "PRN.dat", "aux", "COM9.log", "LPT2"]
OK = ["console.txt", "mycon", "com10.log", "report", "report.", "notes.txt", "报表.csv"]

d = tempfile.mkdtemp()
s = FileStore(d)

for n in RESERVED:
    try:
        s.save(n, b"x")
    except InvalidNameError as e:
        print("save raised  ", n, "->", e)
    else:
        print("!! NO RAISE  ", n)
    try:
        sanitize(n)
    except InvalidNameError as e:
        print("sanitize ok  ", n)
    else:
        print("!! sanitize  ", n)
print("dir after reserved:", os.listdir(d), "names:", s.list_names())

for n in ["...", "   ", ".", "..", " . ", "\t\n"]:
    try:
        s.save(n, b"x")
    except InvalidNameError as e:
        print("blank raised ", repr(n), "->", e)
    else:
        print("!! NO RAISE  ", repr(n))

print("sanitize('report.') =", repr(sanitize("report.")))
s.save("report", b"one")
s.save("report.", b"two")
s.save("report   ", b"three")
print("list_names:", s.list_names(), "dir:", sorted(os.listdir(d)))
print("load('report.') =", s.load("report."))

for n in OK:
    print("ok save", repr(n), "->", repr(s.save(n, b"payload")))

print("exists('CON.txt'):", s.exists("CON.txt"))
print("delete('CON.txt'):", s.delete("CON.txt"))
print("delete('report.'):", s.delete("report."), "names:", s.list_names())
try:
    s.load("CON.txt")
except InvalidNameError as e:
    print("load raised:", e)
try:
    s.target_path("lpt1.tar.gz")
except InvalidNameError as e:
    print("target_path raised:", e)

long_name = "a" * 300 + "."
print("long ->", len(sanitize(long_name)), repr(sanitize(long_name)[-5:]))
print("long reserved ->", end=" ")
try:
    print(repr(sanitize("CON.txt" + "z" * 300)))
except InvalidNameError as e:
    print("raised", e)
print("final dir:", sorted(os.listdir(d)))
